use std::cell::RefCell;

#[derive(Default)]
struct Runtime {
    input: Vec<u8>,
    output: Vec<u8>,
}
thread_local! { static RUNTIME: RefCell<Runtime> = RefCell::new(Runtime::default()); }
#[unsafe(no_mangle)]
pub extern "C" fn oracle_abi_version() -> u32 {
    1
}
#[unsafe(no_mangle)]
pub extern "C" fn oracle_input_resize(length: u32) -> *mut u8 {
    if length > 16 * 1024 * 1024 {
        RUNTIME.with_borrow_mut(|runtime| runtime.input.clear());
        return std::ptr::null_mut();
    }
    RUNTIME.with_borrow_mut(|runtime| {
        runtime.input.resize(length as usize, 0);
        runtime.input.as_mut_ptr()
    })
}
#[unsafe(no_mangle)]
pub extern "C" fn oracle_dispatch() {
    RUNTIME.with_borrow_mut(|runtime| {
        runtime.output =
            serde_json::to_vec(&crate::dispatch(&runtime.input)).expect("serialize oracle reply");
    });
}
#[unsafe(no_mangle)]
pub extern "C" fn oracle_output_ptr() -> *const u8 {
    RUNTIME.with_borrow(|runtime| runtime.output.as_ptr())
}
#[unsafe(no_mangle)]
pub extern "C" fn oracle_output_len() -> u32 {
    RUNTIME.with_borrow(|runtime| runtime.output.len() as u32)
}

use std::io::{self, BufRead, Write};

fn main() {
    let mut output = io::BufWriter::new(io::stdout().lock());
    for input in io::stdin().lock().lines() {
        let input = input.expect("read oracle request");
        serde_json::to_writer(&mut output, &idealis_oracle::dispatch(input.as_bytes()))
            .expect("serialize oracle response");
        output.write_all(b"\n").expect("write newline");
        output.flush().expect("flush oracle response");
    }
}

use idealis_oracle::dispatch;
use serde_json::{Value, json};
fn request() -> Value {
    json!({"version":1,"group":"wire","reference":"oracle","implementations":["native","wasm"],"cases":[
        {"id":"one","input":{"source":"model"},"reference":{"kind":"value","value":7},"actual":[{"kind":"value","value":7},{"kind":"value","value":8}]}
    ]})
}
#[test]
fn json_batches_use_the_same_group_and_preserve_inputs_and_failures() {
    let reply = dispatch(&serde_json::to_vec(&request()).unwrap());
    assert_eq!(reply["kind"], "checked");
    assert_eq!(reply["report"]["status"], "mismatch");
    assert_eq!(
        reply["report"]["cases"][0]["case"]["input"],
        json!({"source":"model"})
    );
    assert_eq!(
        reply["report"]["cases"][0]["comparisons"][0]["status"],
        "matched"
    );
    let mut input = request();
    input["cases"][0]["reference"] = json!({"kind":"unknown","reason":"budget"});
    let reply = dispatch(&serde_json::to_vec(&input).unwrap());
    assert_eq!(reply["report"]["status"], "unknown");
}
#[test]
fn malformed_or_vacuous_batches_cannot_match() {
    for path in ["version", "cases", "actual", "extra", "duplicate"] {
        let mut input = request();
        match path {
            "version" => input["version"] = json!(2),
            "cases" => input["cases"] = json!([]),
            "actual" => input["cases"][0]["actual"] = json!([]),
            "extra" => input["typo"] = json!(true),
            "duplicate" => input["implementations"] = json!(["native", "native"]),
            _ => unreachable!(),
        }
        assert_eq!(
            dispatch(&serde_json::to_vec(&input).unwrap())["kind"],
            "error",
            "{path}"
        );
    }
    assert_eq!(dispatch(b"not json")["kind"], "error");
}

