use serde::{Deserialize, Serialize};
use std::fmt::{Debug, Display, Formatter};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Error(pub String);

impl Display for Error {
    fn fmt(&self, formatter: &mut Formatter<'_>) -> std::fmt::Result {
        formatter.write_str(&self.0)
    }
}
impl std::error::Error for Error {}

#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum Status {
    Matched,
    Mismatch,
    Invalid,
    Unknown,
    Error,
}

impl Status {
    pub(crate) fn aggregate(values: impl Iterator<Item = Self>) -> Self {
        values
            .max_by_key(|status| match status {
                Self::Matched => 0,
                Self::Invalid => 1,
                Self::Unknown => 2,
                Self::Mismatch => 3,
                Self::Error => 4,
            })
            .unwrap_or(Self::Invalid)
    }
}

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(tag = "kind", rename_all = "kebab-case", deny_unknown_fields)]
pub enum Observation<T> {
    Value { value: T },
    Allowed { values: Vec<T> },
    Unknown { reason: String },
    Invalid { reason: String },
    Error { message: String },
}

impl<T> Observation<T> {
    pub fn value(value: T) -> Self {
        Self::Value { value }
    }

    fn failure(&self) -> Option<Status> {
        match self {
            Self::Unknown { .. } => Some(Status::Unknown),
            Self::Invalid { .. } => Some(Status::Invalid),
            Self::Error { .. } => Some(Status::Error),
            _ => None,
        }
    }
}

impl<T, E: Display> From<Result<T, E>> for Observation<T> {
    fn from(result: Result<T, E>) -> Self {
        match result {
            Ok(value) => Self::value(value),
            Err(error) => Self::Error {
                message: error.to_string(),
            },
        }
    }
}

pub(crate) fn compare<T: PartialEq>(reference: &Observation<T>, actual: &Observation<T>) -> Status {
    if reference.failure().is_some() || actual.failure().is_some() {
        return Status::aggregate(reference.failure().into_iter().chain(actual.failure()));
    }
    let Observation::Value { value } = actual else {
        return Status::Invalid;
    };
    let matched = match reference {
        Observation::Value { value: expected } => value == expected,
        Observation::Allowed { values } if !values.is_empty() => values.contains(value),
        _ => return Status::Invalid,
    };
    if matched {
        Status::Matched
    } else {
        Status::Mismatch
    }
}

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Case<I> {
    pub id: String,
    pub input: I,
}

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Comparison<O> {
    pub id: String,
    pub status: Status,
    pub actual: Observation<O>,
}

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct CaseReport<I, O> {
    pub case: Case<I>,
    pub reference: Observation<O>,
    pub comparisons: Vec<Comparison<O>>,
}

#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields)]
pub struct CheckReport<I, O> {
    pub version: u32,
    pub group: String,
    pub reference: String,
    pub implementations: Vec<String>,
    pub status: Status,
    pub cases: Vec<CaseReport<I, O>>,
}

impl<I: Debug, O: Debug> CheckReport<I, O> {
    #[track_caller]
    pub fn assert_matched(&self) {
        assert_eq!(self.status, Status::Matched, "{self:#?}");
    }
}

pub(crate) fn identities<'a>(ids: impl Iterator<Item = &'a str>) -> Result<(), Error> {
    let mut seen = std::collections::BTreeSet::new();
    for id in ids {
        if id.trim().is_empty() || id.len() > 256 || !seen.insert(id) {
            return Err(Error(
                "identities must be nonempty, unique and at most 256 bytes".into(),
            ));
        }
    }
    Ok(())
}

use crate::report::{compare, identities};
use crate::{Case, CaseReport, CheckReport, Comparison, Error, Observation, Status};

type Callback<'a, I, O> = Box<dyn FnMut(&I) -> Observation<O> + 'a>;

pub(crate) struct Implementation<'a, I, O> {
    pub id: String,
    pub run: Callback<'a, I, O>,
}

pub struct OracleGroup<'a, I, O> {
    pub(crate) id: String,
    pub(crate) cases: Vec<Case<I>>,
    references: Vec<Implementation<'a, I, O>>,
    pub(crate) targets: Vec<Implementation<'a, I, O>>,
}

impl<'a, I: Clone, O: Clone + PartialEq> OracleGroup<'a, I, O> {
    pub fn new(id: impl Into<String>) -> Self {
        Self {
            id: id.into(),
            cases: vec![],
            references: vec![],
            targets: vec![],
        }
    }

    pub fn case(&mut self, id: impl Into<String>, input: I) -> &mut Self {
        self.cases.push(Case {
            id: id.into(),
            input,
        });
        self
    }

    pub fn reference(
        &mut self,
        id: impl Into<String>,
        run: impl FnMut(&I) -> Observation<O> + 'a,
    ) -> &mut Self {
        self.references.push(Implementation {
            id: id.into(),
            run: Box::new(run),
        });
        self
    }

    pub fn test_function(
        &mut self,
        id: impl Into<String>,
        run: impl FnMut(&I) -> Observation<O> + 'a,
    ) -> &mut Self {
        self.targets.push(Implementation {
            id: id.into(),
            run: Box::new(run),
        });
        self
    }

    pub(crate) fn validate(&self, require_cases: bool) -> Result<(), Error> {
        identities(std::iter::once(self.id.as_str()))?;
        if self.references.len() != 1
            || self.targets.is_empty()
            || (require_cases && self.cases.is_empty())
        {
            return Err(Error(
                "register exactly one reference, at least one case and one target".into(),
            ));
        }
        identities(
            self.references
                .iter()
                .chain(&self.targets)
                .map(|implementation| implementation.id.as_str()),
        )?;
        identities(self.cases.iter().map(|case| case.id.as_str()))
    }

    pub fn check(&mut self) -> Result<CheckReport<I, O>, Error> {
        self.validate(true)?;
        let mut cases = Vec::new();
        for case in &self.cases {
            let reference = (self.references[0].run)(&case.input);
            let comparisons = self
                .targets
                .iter_mut()
                .map(|target| {
                    let actual = (target.run)(&case.input);
                    Comparison {
                        id: target.id.clone(),
                        status: compare(&reference, &actual),
                        actual,
                    }
                })
                .collect();
            cases.push(CaseReport {
                case: case.clone(),
                reference,
                comparisons,
            });
        }
        Ok(self.report(cases))
    }

    fn report(&self, cases: Vec<CaseReport<I, O>>) -> CheckReport<I, O> {
        CheckReport {
            version: 1,
            group: self.id.clone(),
            reference: self.references[0].id.clone(),
            implementations: self
                .targets
                .iter()
                .map(|target| target.id.clone())
                .collect(),
            status: Status::aggregate(
                cases
                    .iter()
                    .flat_map(|case| case.comparisons.iter().map(|comparison| comparison.status)),
            ),
            cases,
        }
    }

    /// Re-run targets against recorded observations. The reference callback is not called.
    pub fn replay(&mut self, saved: &CheckReport<I, O>) -> Result<CheckReport<I, O>, Error>
    where
        I: PartialEq,
    {
        self.validate(false)?;
        if saved.version != 1
            || saved.group != self.id
            || saved.reference != self.references[0].id
            || saved.implementations
                != self
                    .targets
                    .iter()
                    .map(|target| target.id.clone())
                    .collect::<Vec<_>>()
            || saved.cases.is_empty()
        {
            return Err(Error(
                "saved report does not match group identities or version".into(),
            ));
        }
        identities(saved.cases.iter().map(|case| case.case.id.as_str()))?;
        if !self.cases.is_empty()
            && self.cases
                != saved
                    .cases
                    .iter()
                    .map(|case| case.case.clone())
                    .collect::<Vec<_>>()
        {
            return Err(Error("registered cases differ from recorded inputs".into()));
        }
        for case in &saved.cases {
            if case.comparisons.len() != self.targets.len()
                || case
                    .comparisons
                    .iter()
                    .zip(&self.targets)
                    .any(|(comparison, target)| {
                        comparison.id != target.id
                            || comparison.status != compare(&case.reference, &comparison.actual)
                    })
            {
                return Err(Error(
                    "saved comparison status or identity is inconsistent".into(),
                ));
            }
        }
        if self.report(saved.cases.clone()).status != saved.status {
            return Err(Error("saved aggregate status is inconsistent".into()));
        }
        let cases = saved
            .cases
            .iter()
            .map(|case| CaseReport {
                case: case.case.clone(),
                reference: case.reference.clone(),
                comparisons: self
                    .targets
                    .iter_mut()
                    .map(|target| {
                        let actual = (target.run)(&case.case.input);
                        Comparison {
                            id: target.id.clone(),
                            status: compare(&case.reference, &actual),
                            actual,
                        }
                    })
                    .collect(),
            })
            .collect();
        Ok(self.report(cases))
    }
}

use crate::report::compare;
use crate::{CheckReport, Error, Observation, OracleGroup, Status};
use serde::{Deserialize, Serialize};
use std::fmt::Debug;

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct BenchConfig {
    pub baseline: String,
    pub scope: String,
    pub samples: u32,
    pub warmup: u32,
    pub iterations: u32,
    pub max_evaluations: u64,
}

impl Default for BenchConfig {
    fn default() -> Self {
        Self {
            baseline: String::new(),
            scope: "function call and output construction".into(),
            samples: 20,
            warmup: 3,
            iterations: 1,
            max_evaluations: 1_000_000,
        }
    }
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Statistics {
    pub mean_ns: f64,
    pub median_ns: f64,
    pub min_ns: f64,
    pub max_ns: f64,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct Measurement {
    pub id: String,
    /// Total elapsed nanoseconds for each sample's fixed iterations.
    pub samples_ns: Vec<u64>,
    /// Per-invocation statistics, including only fully completed samples.
    pub statistics: Option<Statistics>,
    /// Baseline median divided by this implementation's median. Only set on a complete matched run.
    pub speedup: Option<f64>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct BenchCase {
    pub id: String,
    pub order: Vec<Vec<String>>,
    pub measurements: Vec<Measurement>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct BenchFailure<O> {
    pub phase: String,
    pub case: String,
    pub implementation: String,
    pub sample: Option<u32>,
    pub iteration: u32,
    pub status: Status,
    pub actual: Observation<O>,
}

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct BenchReport<I, O> {
    pub preflight: CheckReport<I, O>,
    pub config: BenchConfig,
    pub status: Status,
    pub evaluations: u64,
    pub planned_evaluations: u64,
    pub cases: Vec<BenchCase>,
    pub failure: Option<BenchFailure<O>>,
}

impl<I: Debug, O: Debug> BenchReport<I, O> {
    #[track_caller]
    pub fn assert_matched(&self) {
        assert_eq!(self.status, Status::Matched, "{self:#?}");
    }
}

impl<I: Clone, O: Clone + PartialEq> OracleGroup<'_, I, O> {
    #[cfg(not(target_arch = "wasm32"))]
    pub fn bench(&mut self, config: BenchConfig) -> Result<BenchReport<I, O>, Error> {
        let start = std::time::Instant::now();
        self.bench_with_clock(config, || {
            u64::try_from(start.elapsed().as_nanos()).unwrap_or(u64::MAX)
        })
    }

    /// The caller supplies a monotonic nanosecond clock. Comparisons and output destruction are outside it.
    pub fn bench_with_clock(
        &mut self,
        config: BenchConfig,
        mut clock: impl FnMut() -> u64,
    ) -> Result<BenchReport<I, O>, Error> {
        self.validate(true)?;
        if config.samples == 0
            || config.iterations == 0
            || config.scope.trim().is_empty()
            || !self
                .targets
                .iter()
                .any(|target| target.id == config.baseline)
        {
            return Err(Error(
                "bench needs positive samples/iterations, a scope and a registered target baseline"
                    .into(),
            ));
        }
        let count = self.cases.len() as u64;
        let targets = self.targets.len() as u64;
        let planned_evaluations = u64::from(config.samples)
            .checked_mul(u64::from(config.iterations))
            .and_then(|calls| calls.checked_add(u64::from(config.warmup)))
            .and_then(|calls| calls.checked_add(1))
            .and_then(|calls| calls.checked_mul(targets))
            .and_then(|calls| calls.checked_add(1))
            .and_then(|calls| calls.checked_mul(count))
            .ok_or_else(|| Error("evaluation count overflow".into()))?;
        if planned_evaluations > config.max_evaluations {
            return Err(Error(format!(
                "planned {planned_evaluations} evaluations exceed max_evaluations"
            )));
        }
        let preflight = self.check()?;
        let mut report = BenchReport {
            status: preflight.status,
            evaluations: count * (targets + 1),
            planned_evaluations,
            cases: self
                .cases
                .iter()
                .map(|case| BenchCase {
                    id: case.id.clone(),
                    order: vec![],
                    measurements: self
                        .targets
                        .iter()
                        .map(|target| Measurement {
                            id: target.id.clone(),
                            samples_ns: vec![],
                            statistics: None,
                            speedup: None,
                        })
                        .collect(),
                })
                .collect(),
            config,
            preflight,
            failure: None,
        };
        if report.status != Status::Matched {
            return Ok(report);
        }
        let mut previous_tick = None;
        'cases: for (case_index, case) in self.cases.iter().enumerate() {
            let reference = &report.preflight.cases[case_index].reference;
            for iteration in 0..report.config.warmup {
                for target in &mut self.targets {
                    let actual = (target.run)(&case.input);
                    report.evaluations += 1;
                    let status = compare(reference, &actual);
                    if status != Status::Matched {
                        report.failure = Some(BenchFailure {
                            phase: "warmup".into(),
                            case: case.id.clone(),
                            implementation: target.id.clone(),
                            sample: None,
                            iteration,
                            status,
                            actual,
                        });
                        report.status = status;
                        break 'cases;
                    }
                }
            }
            for sample in 0..report.config.samples {
                let offset = (sample as usize / 2) % self.targets.len();
                let mut order = (0..self.targets.len())
                    .map(|index| (offset + index) % self.targets.len())
                    .collect::<Vec<_>>();
                if sample % 2 == 1 {
                    order.reverse();
                }
                report.cases[case_index].order.push(
                    order
                        .iter()
                        .map(|index| self.targets[*index].id.clone())
                        .collect(),
                );
                for target_index in order {
                    let target = &mut self.targets[target_index];
                    let mut elapsed = 0_u64;
                    for iteration in 0..report.config.iterations {
                        let start = clock();
                        let actual =
                            std::hint::black_box((target.run)(std::hint::black_box(&case.input)));
                        let end = clock();
                        report.evaluations += 1;
                        let status = compare(reference, &actual);
                        if status != Status::Matched {
                            report.failure = Some(BenchFailure {
                                phase: "sample".into(),
                                case: case.id.clone(),
                                implementation: target.id.clone(),
                                sample: Some(sample),
                                iteration,
                                status,
                                actual,
                            });
                            report.status = status;
                            break 'cases;
                        }
                        let duration = end
                            .checked_sub(start)
                            .filter(|duration| *duration > 0)
                            .filter(|_| previous_tick.is_none_or(|previous| start >= previous));
                        previous_tick = Some(end);
                        let total = duration.and_then(|duration| elapsed.checked_add(duration));
                        let Some(total) = total else {
                            report.status = Status::Unknown;
                            report.failure = Some(BenchFailure { phase: "clock".into(), case: case.id.clone(), implementation: target.id.clone(), sample: Some(sample), iteration, status: Status::Unknown, actual: Observation::Unknown { reason: "clock must advance monotonically without zero intervals or overflow".into() } });
                            break 'cases;
                        };
                        elapsed = total;
                    }
                    report.cases[case_index].measurements[target_index]
                        .samples_ns
                        .push(elapsed);
                }
            }
        }
        for case in &mut report.cases {
            for measurement in &mut case.measurements {
                if measurement.samples_ns.is_empty() {
                    continue;
                }
                let mut sorted = measurement
                    .samples_ns
                    .iter()
                    .map(|sample| *sample as f64 / f64::from(report.config.iterations))
                    .collect::<Vec<_>>();
                sorted.sort_by(f64::total_cmp);
                let middle = sorted.len() / 2;
                measurement.statistics = Some(Statistics {
                    mean_ns: sorted.iter().sum::<f64>() / sorted.len() as f64,
                    median_ns: if sorted.len() % 2 == 0 {
                        (sorted[middle - 1] + sorted[middle]) / 2.0
                    } else {
                        sorted[middle]
                    },
                    min_ns: sorted[0],
                    max_ns: sorted[sorted.len() - 1],
                });
            }
            if report.status == Status::Matched {
                let baseline = case
                    .measurements
                    .iter()
                    .find(|measurement| measurement.id == report.config.baseline)
                    .and_then(|measurement| measurement.statistics.as_ref())
                    .expect("completed baseline")
                    .median_ns;
                for measurement in &mut case.measurements {
                    measurement.speedup = measurement
                        .statistics
                        .as_ref()
                        .map(|statistics| baseline / statistics.median_ns);
                }
            }
        }
        Ok(report)
    }
}

